// Reshape FastAPI response to the legacy shape that downstream consumers expect.
const r = $input.first().json;
const products = r.products || [];
return [{
  json: {
    wayfair_products: products.map(p => ({
      url: p.url,
      name: p.name,
      price: p.price,
      details: p.details || [],
      pattern: p.pattern || '',
      image_url: p.image_url || '',
      rating: p.rating || '',
      review_count: p.review_count || '',
      scraped_at: r.scraped_at || new Date().toISOString(),
    })),
    totalWayfair: products.length,
    totalProducts: products.length,
    scrapedAt: r.scraped_at || new Date().toISOString(),
  },
}];

// RESHAPE IKEA RESPONSE
// Convert Apify's individual product items into one array
// matching the Amazon/Wayfair structure.

const products = $input.all()
  .slice(0, 10)
  .map(item => item.json)
  .map(p => ({
    retailer: "IKEA",
    name: p.name ?? p.title ?? null,
    price: p.price ?? p.formattedPrice ?? null,
    rating: p.rating ?? null,
    review_count: p.reviewCount ?? p.review_count ?? null,
    url: p.url ?? p.product_url ?? null,
    image_url: p.image ?? p.mainImage ?? p.image_url ?? null,
    category: p.category ?? null
  }));

return [{
  json: {
    ikeaProducts: products,
    totalIkeaProducts: products.length,
    totalProducts: products.length,
    scrapedAt: new Date().toISOString()
  }
}];

